import { useLayoutEffect } from "react";
import { setPageMeta } from "../lib/meta";

/**
 * Shown for any path the app does not know. It plays no intro and starts no
 * scroll engine: it is a plain page with a way home.
 */
export function NotFoundPage() {
  useLayoutEffect(() => {
    setPageMeta("Not found: Axiom", "No page lives at this address.");
  }, []);

  return (
    <main>
      <section className="sec" aria-labelledby="missing-h">
        <div className="sc-wrap">
          <div className="head">
            <h2 id="missing-h">Not found.</h2>
          </div>
          <div className="prose">
            <p>
              No page lives at this address. <a href="/">Back to the Axiom home page</a>.
            </p>
          </div>
        </div>
      </section>
    </main>
  );
}
