/*
 * The portal: a swirling blur washes over the screen, the page changes while the
 * screen is fully covered, and the cover clears. It is the climb back to the top
 * (initSite) and the transition between routes (router). Only opacity and
 * transform are animated; the blur is the one static layer.
 */
const IN = 950;
const OUT = 1300;

export interface SwirlOptions {
  /** Runs once the screen is fully covered. Do the jump or the page swap here. */
  onCovered: () => void;
  /** Runs two frames after onCovered, as the cover starts to clear. */
  onClearing?: () => void;
  /** Runs once the cover is gone. */
  onDone?: () => void;
}

/** Plays the portal. Returns a cancel that removes the cover at once. */
export function playSwirl({ onCovered, onClearing, onDone }: SwirlOptions): () => void {
  let dead = false;
  const ov = document.createElement("div");
  ov.className = "swirl";
  ov.setAttribute("aria-hidden", "true");
  ov.innerHTML = "<i></i><i></i>";
  document.body.appendChild(ov);

  const arms = Array.from(ov.children) as HTMLElement[];
  const split = IN / (IN + OUT);
  arms[0].animate(
    [
      { transform: "rotate(0deg) scale(.3)" },
      { transform: "rotate(260deg) scale(1)", offset: split },
      { transform: "rotate(520deg) scale(.7)" },
    ],
    { duration: IN + OUT + 120, easing: "cubic-bezier(.45,.05,.4,1)", fill: "forwards" },
  );
  arms[1].animate(
    [
      { transform: "rotate(0deg) scale(.4)" },
      { transform: "rotate(-320deg) scale(1.05)", offset: split },
      { transform: "rotate(-600deg) scale(.8)" },
    ],
    { duration: IN + OUT + 120, easing: "cubic-bezier(.45,.05,.4,1)", fill: "forwards" },
  );

  const fadeIn = ov.animate([{ opacity: 0 }, { opacity: 1 }], {
    duration: IN,
    easing: "cubic-bezier(.55,0,.75,.45)",
    fill: "forwards",
  });
  fadeIn.onfinish = () => {
    if (dead) return;
    // The jump or swap is the one expensive frame. It happens while the screen is
    // fully covered, and the clear-out waits two frames.
    onCovered();
    requestAnimationFrame(() =>
      requestAnimationFrame(() => {
        if (dead) return;
        onClearing?.();
        const fadeOut = ov.animate([{ opacity: 1 }, { opacity: 0 }], {
          duration: OUT,
          easing: "cubic-bezier(.2,.6,.3,1)",
          fill: "forwards",
        });
        fadeOut.onfinish = () => {
          if (dead) return;
          dead = true;
          ov.remove();
          onDone?.();
        };
      }),
    );
  };

  return () => {
    if (dead) return;
    dead = true;
    ov.remove();
  };
}
