const DEFAULT_TITLE = "Deprecated: tools no longer developed";
const DESCRIPTION = "A tool on Axiom has been deprecated.";

interface KnownTool {
  name: string;
  replacement: string;
  replacementUrl: string;
  body: string;
  extra: string;
}

const KNOWN_TOOLS: Readonly<Record<string, KnownTool>> = {
  jiggle: {
    name: "Jiggle",
    replacement: "poly",
    replacementUrl: "/poly",
    body: "Jiggle has been deprecated in favor of poly.",
    extra: "The Jiggle repo has been archived. The code and history stay public.",
  },
};

/** The tool named by ?tool=, trimmed and capped the way the original page capped it. */
function toolFromSearch(search: string): string {
  return (new URLSearchParams(search).get("tool") ?? "").trim().slice(0, 64);
}

function knownTool(key: string): KnownTool | null {
  const id = key.toLowerCase();
  return Object.prototype.hasOwnProperty.call(KNOWN_TOOLS, id) ? KNOWN_TOOLS[id] : null;
}

/** The message section. Its text depends on ?tool=, as the original inline script did. */
function DeprecatedMessage({ tool }: { tool: string }) {
  const entry = tool ? knownTool(tool) : null;
  const name = entry ? entry.name : tool;

  let title = "No tool named.";
  let body: ReactNode = (
    <>
      Add <code>?tool=name</code> to the link to see a message for that tool.
    </>
  );
  let extra: string | null = null;

  if (tool) {
    title = `${name} is deprecated.`;
    if (entry) {
      body = (
        <>
          {entry.body + " "}
          <a href={entry.replacementUrl}>{entry.replacement}</a>.
        </>
      );
      extra = entry.extra;
    } else {
      body = "This tool is no longer being developed. Check the Axiom home page for the tools that are still active.";
    }
  }

  return (
    <section className="sec" id="message" data-sc-act="flow" aria-labelledby="msg-title">
      <div className="sc-wrap">
        <div className="head">
          <h2 id="msg-title">{title}</h2>
        </div>
        <div className="prose">
          <p id="msg-body">{body}</p>
          <p id="msg-extra" hidden={extra === null}>
            {extra ?? ""}
          </p>
        </div>
      </div>
    </section>
  );
}

