/*
 * Intro planning for the app.
 *
 * Rules:
 *  - The homepage loading screen plays only when the first page the visitor
 *    loads is the homepage, and only once per session.
 *  - A sub-page plays its entrance (the hero letters, tags and tagline rise in)
 *    only when the session started on a sub-page, and only for the first
 *    sub-page the visitor sees. Every later sub-page in that session shows its
 *    content immediately.
 *  - Reduced motion plays neither.
 *
 * The flags below are module-level and are read once when the module loads,
 * which is before the first render, so they describe the first page load.
 */
import "../vendor/scrollcraft/scrollcraft.js";
import { canonicalPath } from "../router/paths";

export type IntroKind = "home" | "sub";
export type IntroPlan = "loader" | "entrance" | "none";

// The first page the visitor loaded, recorded before any navigation happens.
const ENTRY_PATH = canonicalPath(window.location.pathname);
const SESSION_STARTED_ON_HOME = ENTRY_PATH === "/";

let homeLoaderSpent = false;
let subPageIntroSpent = false;

/**
 * Returns what the page being mounted should play. Each call that returns a
 * playing plan spends that intro, so call it once per mount (the page components
 * do this from a lazy state initializer).
 */
export function planIntro(kind: IntroKind): IntroPlan {
  if (window.ScrollCraft.reduce) return "none";

  if (kind === "home") {
    if (SESSION_STARTED_ON_HOME && !homeLoaderSpent) {
      homeLoaderSpent = true;
      return "loader";
    }
    return "none";
  }

  if (!SESSION_STARTED_ON_HOME && !subPageIntroSpent) {
    subPageIntroSpent = true;
    return "entrance";
  }
  return "none";
}
