/*
 * Connects a page component to the site behaviour. The page renders its markup;
 * this hook does everything that touches the document: body and root classes,
 * the intro classes, the page meta, and the scroll engine's lifetime.
 *
 * A page component is mounted once per visit (the router keys it by route), so
 * the effects below run once per visit and their cleanups run when the visitor
 * leaves. Do not run the pages under StrictMode: the intro decision is spent the
 * first time it is taken.
 */
import { useEffect, useLayoutEffect, type RefObject } from "react";
import { setPageMeta } from "../lib/meta";
import { initSite, type SiteKind } from "./initSite";
import type { IntroPlan } from "./intro";

export interface SitePageOptions {
  kind: SiteKind;
  plan: IntroPlan;
  title: string;
  description: string;
  rootRef: RefObject<HTMLElement | null>;
  /** Only the homepage has a loading overlay. */
  loaderRef?: RefObject<HTMLDivElement | null>;
}

export function useSitePage({ kind, plan, title, description, rootRef, loaderRef }: SitePageOptions): void {
  // Body and root classes must be in place before the first paint, so the
  // entrance animations start from their from-state rather than flashing.
  useLayoutEffect(() => {
    const html = document.documentElement;
    const body = document.body;
    body.dataset.page = kind === "home" ? "home" : "doc";
    if (plan === "loader") html.classList.add("intro-on");
    if (plan === "entrance") html.classList.add("intro-out");
    return () => {
      html.classList.remove("intro-on", "intro-out");
      delete body.dataset.page;
    };
  }, [kind, plan]);

  // Meta is separate so a page whose title changes (the deprecated page) does not
  // re-run the intro classes above.
  useLayoutEffect(() => {
    setPageMeta(title, description);
  }, [title, description]);

  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    return initSite({ kind, root, loader: loaderRef?.current ?? null, plan });
    // Run once per mount. The router keys pages by route, so a visit is a mount.
  }, []);
}
