/**
 * The route table. Every page is a clean path. Nothing is reachable through a
 * .html URL: those are canonicalized to the clean path (and redirected by the
 * server, see scripts/serve.ts and the hosting files).
 */

export type PageId = "home" | "poly" | "vfsx" | "knit" | "deprecated";

const PAGE_PATHS: Readonly<Record<string, PageId>> = {
  "/": "home",
  "/poly": "poly",
  "/vfsx": "vfsx",
  "/knit": "knit",
  "/deprecated": "deprecated",
};

/** Old paths that move somewhere else. Values may carry their own query string. */
const REDIRECTS: Readonly<Record<string, string>> = {
  "/jiggle": "/deprecated?tool=jiggle",
};

export type Resolution =
  | { kind: "page"; page: PageId }
  | { kind: "redirect"; to: string }
  | { kind: "missing" };

function has(table: object, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(table, key);
}

/**
 * Turns any pathname into its clean form: trailing slashes removed, a trailing
 * .html removed, and /index mapped to /. /index.html therefore behaves exactly
 * like /.
 */
export function canonicalPath(pathname: string): string {
  let p = pathname || "/";
  if (p.length > 1) p = p.replace(/\/+$/, "") || "/";
  if (p.endsWith(".html")) {
    p = p.slice(0, -".html".length) || "/";
    if (p === "/index") p = "/";
  }
  return p;
}

export function resolveRoute(pathname: string): Resolution {
  const path = canonicalPath(pathname);
  if (has(REDIRECTS, path)) return { kind: "redirect", to: REDIRECTS[path] };
  if (has(PAGE_PATHS, path)) return { kind: "page", page: PAGE_PATHS[path] };
  return { kind: "missing" };
}

/** Where the address bar should point for this location, or null if it already does. */
export function normalizedUrl(loc: { pathname: string; search: string; hash: string }): string | null {
  const resolution = resolveRoute(loc.pathname);
  if (resolution.kind === "redirect") return resolution.to + loc.hash;
  const canonical = canonicalPath(loc.pathname);
  if (canonical !== loc.pathname) return canonical + loc.search + loc.hash;
  return null;
}
