/*
 * A small client router built on the History API. Routes are real URLs, the
 * server serves the app for any path, and in-app links navigate without a page
 * reload. The current location lives in a module store that React reads with
 * useSyncExternalStore, so every component sees the same URL.
 *
 * It is deliberately small. The route table is in ./paths.ts.
 */
import { useSyncExternalStore } from "react";
import { flushSync } from "react-dom";
import { playSwirl } from "../site/swirl";
import { normalizedUrl, resolveRoute } from "./paths";

export interface AppLocation {
  pathname: string;
  search: string;
  hash: string;
}

function readLocation(): AppLocation {
  return {
    pathname: window.location.pathname,
    search: window.location.search,
    hash: window.location.hash,
  };
}

let current: AppLocation = readLocation();
const subscribers = new Set<() => void>();

function subscribe(onChange: () => void): () => void {
  subscribers.add(onChange);
  return () => {
    subscribers.delete(onChange);
  };
}

function getSnapshot(): AppLocation {
  return current;
}

function publish(): void {
  current = readLocation();
  subscribers.forEach((fn) => fn());
}

// A new page starts at the top, unless the URL asks for a fragment.
function scrollToTop(): void {
  window.scrollTo({ top: 0, behavior: "instant" });
}

// Only one portal plays at a time. A change that arrives during one is applied at once.
let portalBusy = false;

/**
 * Applies a route change. When it changes the page, the portal covers the screen,
 * the change is applied while the screen is covered, and the cover clears. The
 * update runs inside flushSync so React has committed the new page before the
 * cover clears. Reduced motion skips the portal.
 */
function transitionTo(update: () => void, portal: boolean): void {
  const reduce = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (!portal || reduce || portalBusy || !document.body.animate) {
    flushSync(update);
    return;
  }
  portalBusy = true;
  playSwirl({
    onCovered: () => flushSync(update),
    onDone: () => {
      portalBusy = false;
    },
  });
}

/** Moves to a URL inside the app. Replace skips the history entry and does not scroll. */
export function navigate(to: string, options: { replace?: boolean } = {}): void {
  const url = new URL(to, window.location.href);
  const path = url.pathname + url.search + url.hash;
  if (options.replace) {
    // Redirects run during render, so they must not start a transition.
    window.history.replaceState(null, "", path);
    publish();
    return;
  }
  const pathChanged = url.pathname !== window.location.pathname;
  transitionTo(() => {
    // Scroll while the screen is covered, so the jump is never seen.
    if (pathChanged && !url.hash) scrollToTop();
    window.history.pushState(null, "", path);
    publish();
  }, pathChanged && !url.hash);
}

/** The current location. Components re-render when it changes. */
export function useAppLocation(): AppLocation {
  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
}

/**
 * Called once before the first render. Rewrites the address bar when the URL is
 * not the canonical one, such as /index.html, /poly.html, /poly/ or /jiggle.
 */
export function normalizeInitialUrl(): void {
  const next = normalizedUrl(readLocation());
  if (next !== null) window.history.replaceState(null, "", next);
  current = readLocation();
}

/** Installs the back/forward listener and the in-app link interception. */
export function installRouter(): () => void {
  const onPop = (): void => {
    const before = current.pathname;
    const next = readLocation();
    const pathChanged = next.pathname !== before && !next.hash;
    transitionTo(() => {
      if (pathChanged) scrollToTop();
      publish();
    }, pathChanged);
  };

  const onClick = (e: MouseEvent): void => {
    if (e.defaultPrevented || e.button !== 0) return;
    if (e.metaKey || e.ctrlKey || e.shiftKey || e.altKey) return;
    const target = e.target as Element | null;
    const a = target && typeof target.closest === "function" ? target.closest("a[href]") : null;
    if (!(a instanceof HTMLAnchorElement)) return;
    if (a.target && a.target !== "_self") return;
    if (a.hasAttribute("download")) return;
    const raw = a.getAttribute("href") ?? "";
    if (raw.startsWith("#")) return; // in-page fragments belong to the page

    const url = new URL(a.href);
    if (url.origin !== window.location.origin) return;
    const resolution = resolveRoute(url.pathname);
    if (resolution.kind === "missing") return; // static files such as the spec markdown

    e.preventDefault();
    const to = resolution.kind === "redirect" ? resolution.to : url.pathname + url.search + url.hash;
    navigate(to);
  };

  window.addEventListener("popstate", onPop);
  document.addEventListener("click", onClick);
  return () => {
    window.removeEventListener("popstate", onPop);
    document.removeEventListener("click", onClick);
  };
}
