/*
 * Paint splats. One canvas per splat, drawn from a clock and never from scroll
 * position. A splat bursts from an impact point with ragged fingers, throws
 * droplets ahead of itself, floods the stage in three pigment layers, then
 * freezes as a flat fill and stops drawing. Resetting is instant and only
 * happens while the stage is entirely off screen, so there is never a
 * half-splash to see.
 *
 * Ported from paint.js. The only behavioural change is that a splat now has a
 * destroy() which removes its resize listener, because a single-page app mounts
 * and unmounts these on every navigation.
 */

export type PaintState = "idle" | "running" | "done";

export interface PaintHandle {
  play(): void;
  reset(): void;
  state(): PaintState;
  destroy(): void;
}

type PaletteName = "blue" | "dark";
type Palette = readonly [string, string, string];

const TAU = Math.PI * 2;
const reduce = typeof window.matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;

const PALETTES: Record<PaletteName, Palette> = {
  blue: ["#5b74ff", "#2d4bff", "#1638ff"],
  dark: ["#5a554d", "#2b2825", "#0d0c0b"],
};

// Timeline, in seconds. Layer 0 leads, layers 1 and 2 follow it.
const DELAY = [0, 0.14, 0.28] as const;
const DUR = 2.3;
const TOTAL = DELAY[2] + DUR;
const POINTS = 360;

interface Wobble { f: number; a: number; p: number }
interface Finger { a: number; w: number; len: number }
interface Drop { a: number; d: number; s: number; l: number; f: number; c: 0 | 1 }
interface Shape { wob: Wobble[]; fingers: Finger[]; drops: Drop[] }

function mulberry(seed: number): () => number {
  let a = seed | 0;
  return function () {
    a |= 0;
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function clamp01(x: number): number {
  return x < 0 ? 0 : x > 1 ? 1 : x;
}

function smooth(u: number): number {
  const v = clamp01(u);
  return v * v * (3 - 2 * v);
}

// Fast burst, slow creep.
function spread(u: number): number {
  return 1 - Math.pow(1 - clamp01(u), 2.3);
}

function shade(hex: string, f: number): string {
  const n = parseInt(hex.slice(1), 16);
  const r = Math.round(((n >> 16) & 255) * f);
  const g = Math.round(((n >> 8) & 255) * f);
  const b = Math.round((n & 255) * f);
  return `rgb(${r},${g},${b})`;
}

function wrapPi(d: number): number {
  let v = (d + Math.PI) % TAU;
  if (v < 0) v += TAU;
  return v - Math.PI;
}

class Splat {
  private readonly c: HTMLCanvasElement;
  private readonly g: CanvasRenderingContext2D;
  private readonly pal: Palette;
  private readonly ox: number;
  private readonly oy: number;
  private mode: PaintState = "idle";
  private raf = 0;
  private t0 = 0;
  private shape: Shape | null = null;
  private w = 1;
  private h = 1;
  private readonly k = 1; // soft blobs do not need retina pixels; this cuts fill cost 2 to 4x
  private readonly onResize: () => void;

  constructor(canvas: HTMLCanvasElement) {
    const ctx = canvas.getContext("2d");
    if (!ctx) throw new Error("paint: 2d canvas context unavailable");
    this.c = canvas;
    this.g = ctx;
    const name = canvas.getAttribute("data-paint");
    this.pal = name === "dark" || name === "blue" ? PALETTES[name] : PALETTES.blue;
    const ox = parseFloat(canvas.getAttribute("data-ox") ?? "");
    const oy = parseFloat(canvas.getAttribute("data-oy") ?? "");
    this.ox = isNaN(ox) ? 0.5 : ox;
    this.oy = isNaN(oy) ? 0.1 : oy;
    this.measure();
    this.onResize = () => {
      this.measure();
      if (this.mode === "done") this.solid();
    };
    window.addEventListener("resize", this.onResize, { passive: true });
  }

  destroy(): void {
    window.removeEventListener("resize", this.onResize);
    cancelAnimationFrame(this.raf);
    this.mode = "idle";
  }

  state(): PaintState {
    return this.mode;
  }

  private measure(): void {
    const c = this.c;
    this.w = c.clientWidth || 1;
    this.h = c.clientHeight || 1;
    c.width = Math.max(1, Math.round(this.w * this.k));
    c.height = Math.max(1, Math.round(this.h * this.k));
  }

  // Fresh randomness for every play, fixed for the length of that play.
  private build(): void {
    const rnd = mulberry((Math.random() * 4294967296) >>> 0);
    const wob: Wobble[] = [];
    const freqs = [2, 3, 5];
    const amps = [0.075, 0.05, 0.035];
    for (let i = 0; i < 3; i++) {
      wob.push({ f: freqs[i], a: amps[i] * (0.7 + rnd() * 0.6), p: rnd() * TAU });
    }

    const nF = 9 + Math.floor(rnd() * 4);
    const fingers: Finger[] = [];
    for (let i = 0; i < nF; i++) {
      fingers.push({
        a: ((i + rnd() * 0.8) / nF) * TAU,
        w: 0.07 + rnd() * 0.16,
        len: 0.18 + rnd() * 0.5,
      });
    }

    const drops: Drop[] = [];
    const nD = 22;
    for (let i = 0; i < nD; i++) {
      const big = rnd();
      const d = 0.5 + rnd() * 0.5;
      const l = rnd() * 0.14;
      drops.push({
        a: rnd() * TAU,
        d, // landing distance, as a fraction of the far corner
        s: 3 + Math.pow(big, 2.2) * 24, // radius in css px, scaled to the stage when drawn
        l, // launch time
        f: 0.22 + rnd() * 0.3 + (d - 0.5) * 0.3, // flight time
        c: rnd() < 0.7 ? 0 : 1,
      });
    }
    this.shape = { wob, fingers, drops };
  }

  private radius(th: number, layer: number, u: number): number {
    const s = this.shape;
    if (!s) return 0;
    let v = 1;
    for (const wb of s.wob) v += wb.a * Math.sin(wb.f * th + wb.p + layer * 0.5);
    // Fingers are longest in the first instant and relax as the splat settles.
    const relax = 1 - 0.5 * smooth(u);
    const lay = 1 - 0.22 * layer;
    for (const f of s.fingers) {
      v += f.len * relax * lay * Math.exp(-Math.pow(Math.abs(wrapPi(th - f.a)) / f.w, 1.6));
    }
    return v;
  }

  private solid(): void {
    const g = this.g;
    g.setTransform(1, 0, 0, 1, 0, 0);
    g.clearRect(0, 0, this.c.width, this.c.height);
    g.fillStyle = this.pal[2];
    g.fillRect(0, 0, this.c.width, this.c.height);
  }

  private clear(): void {
    this.g.setTransform(1, 0, 0, 1, 0, 0);
    this.g.clearRect(0, 0, this.c.width, this.c.height);
  }

  private draw(t: number): void {
    const shape = this.shape;
    if (!shape) return;
    const g = this.g;
    const w = this.w;
    const h = this.h;
    const ox = this.ox * w;
    const oy = this.oy * h;
    const far = Math.max(
      Math.hypot(ox, oy),
      Math.hypot(w - ox, oy),
      Math.hypot(ox, h - oy),
      Math.hypot(w - ox, h - oy),
    );
    const rmax = far / 0.74;
    const scale = Math.min(w, h) / 900;
    const depth = Math.max(5, 10 * Math.min(scale, 1.3)); // how thick the paint stands, in css px

    g.setTransform(this.k, 0, 0, this.k, 0, 0);
    g.clearRect(0, 0, w, h);

    // Droplets, underneath. The layers swallow them as the front arrives.
    // Light comes from the top left: each drop casts a shadow down and right
    // and carries a small highlight.
    for (const d of shape.drops) {
      if (t < d.l) continue;
      const fl = clamp01((t - d.l) / d.f);
      const dist = d.d * far * (1 - (1 - fl) * (1 - fl));
      const x = ox + Math.cos(d.a) * dist;
      const y = oy + Math.sin(d.a) * dist;
      if (x < -40 || x > w + 40 || y < -40 || y > h + 40) continue;
      const r = d.s * Math.max(scale, 0.55);
      const landed = clamp01((t - d.l - d.f) / 0.3);
      const pop = 1 + 0.28 * Math.sin(landed * Math.PI);
      const rx = r * (1 + 1.8 * (1 - fl)) * pop;
      const ry = r * (1 - 0.2 * (1 - fl)) * pop;
      const lift = 1 + 3 * (1 - fl); // a drop in flight sits higher over its shadow
      g.fillStyle = "rgba(0,0,0,.28)";
      g.beginPath();
      g.ellipse(x + r * 0.45 * lift, y + r * 0.6 * lift, rx, ry, d.a, 0, TAU);
      g.fill();
      g.fillStyle = shade(this.pal[d.c], 0.6);
      g.beginPath();
      g.ellipse(x + r * 0.18, y + r * 0.24, rx, ry, d.a, 0, TAU);
      g.fill();
      g.fillStyle = this.pal[d.c];
      g.beginPath();
      g.ellipse(x, y, rx, ry, d.a, 0, TAU);
      g.fill();
      if (r > 5) {
        g.fillStyle = "rgba(255,255,255,.38)";
        g.beginPath();
        g.ellipse(x - rx * 0.32, y - ry * 0.34, rx * 0.26, ry * 0.2, d.a, 0, TAU);
        g.fill();
      }
    }

    // Three pigment layers, outermost first. Each one is a raised slab: a soft
    // shadow on whatever is below, a darker side wall that gives it thickness,
    // then the lit top face with a sheen that fades as the layer settles.
    const pts: number[] = [];
    const n = POINTS * 2;
    for (let L = 0; L < 3; L++) {
      let u = (t - DELAY[L]) / DUR;
      if (u <= 0) continue;
      u = clamp01(u);
      const R = rmax * spread(u);
      pts.length = 0;
      for (let j = 0; j < POINTS; j++) {
        const th = (j / POINTS) * TAU;
        const rr = R * this.radius(th, L, u);
        pts.push(ox + Math.cos(th) * rr, oy + Math.sin(th) * rr);
      }
      const path = new Path2D();
      path.moveTo((pts[n - 2] + pts[0]) / 2, (pts[n - 1] + pts[1]) / 2);
      for (let j = 0; j < POINTS; j++) {
        const a = j * 2;
        const b = ((j + 1) % POINTS) * 2;
        path.quadraticCurveTo(pts[a], pts[a + 1], (pts[a] + pts[b]) / 2, (pts[a + 1] + pts[b + 1]) / 2);
      }
      path.closePath();

      const settle = 1 - smooth(u); // 1 while spreading, 0 once settled
      // shadow: soft and blurred, cast by the top face itself
      g.save();
      g.shadowColor = `rgba(4,8,40,${(0.28 * settle + 0.1).toFixed(3)})`;
      g.shadowBlur = depth * 6;
      g.shadowOffsetX = depth * 0.8;
      g.shadowOffsetY = depth * 2.4;
      g.fillStyle = this.pal[L];
      g.fill(path);
      g.restore();
      // top face
      g.fillStyle = this.pal[L];
      g.fill(path);
      // sheen, lit from the top left
      if (settle > 0.01) {
        g.save();
        g.clip(path);
        const gr = g.createLinearGradient(0, 0, w, h);
        gr.addColorStop(0, `rgba(255,255,255,${(0.17 * settle).toFixed(3)})`);
        gr.addColorStop(0.5, "rgba(255,255,255,0)");
        gr.addColorStop(1, `rgba(0,0,0,${(0.2 * settle).toFixed(3)})`);
        g.fillStyle = gr;
        g.fillRect(0, 0, w, h);
        // bright lip along the lit edge
        g.lineWidth = 3;
        g.strokeStyle = `rgba(255,255,255,${(0.3 * settle).toFixed(3)})`;
        g.translate(1.6, 1.6);
        g.stroke(path);
        g.restore();
      }
    }
  }

  play(): void {
    if (this.mode !== "idle") return;
    this.measure();
    if (reduce) {
      this.mode = "done";
      this.solid();
      return;
    }
    this.build();
    this.mode = "running";
    this.t0 = performance.now();
    const frame = (now: number): void => {
      if (this.mode !== "running") return;
      const t = Math.max((now - this.t0) / 1000, 0);
      if (t >= TOTAL) {
        this.mode = "done";
        this.solid();
        return;
      }
      this.draw(t);
      this.raf = requestAnimationFrame(frame);
    };
    frame(this.t0);
  }

  // Instant. Only call this while the stage is off screen.
  reset(): void {
    if (this.mode === "idle") return;
    cancelAnimationFrame(this.raf);
    this.mode = "idle";
    this.clear();
  }
}

/** Mounts a splat on a canvas. The canvas must carry data-paint and optionally data-ox / data-oy. */
export function mountPaint(canvas: HTMLCanvasElement): PaintHandle {
  const s = new Splat(canvas);
  return {
    play: () => s.play(),
    reset: () => s.reset(),
    state: () => s.state(),
    destroy: () => s.destroy(),
  };
}
