import { useLayoutEffect, type ComponentType, type ReactElement } from "react";
import { DeprecatedPage } from "../pages/DeprecatedPage";
import { HomePage } from "../pages/HomePage";
import { KnitPage } from "../pages/KnitPage";
import { NotFoundPage } from "../pages/NotFoundPage";
import { PolyPage } from "../pages/PolyPage";
import { VfsxPage } from "../pages/VfsxPage";
import { resolveRoute, type PageId } from "../router/paths";
import { navigate, useAppLocation } from "../router/router";

// Each page is its own component, so the router's key is the route itself.
const PAGES: Record<PageId, ComponentType> = {
  home: HomePage,
  poly: PolyPage,
  vfsx: VfsxPage,
  knit: KnitPage,
  deprecated: DeprecatedPage,
};

/** Replaces a legacy URL with its destination without adding a history entry. */
function Redirect({ to }: { to: string }) {
  useLayoutEffect(() => {
    navigate(to, { replace: true });
  }, [to]);
  return null;
}

/**
 * The app shell. The grain, the island header and the page are the same on every
 * route. Only the page changes, and each page owns its own scroll behaviour.
 */
export function App() {
  const location = useAppLocation();
  const resolution = resolveRoute(location.pathname);

  let page: ReactElement;
  if (resolution.kind === "page") {
    const Page = PAGES[resolution.page];
    page = <Page />;
  } else if (resolution.kind === "redirect") {
    page = <Redirect to={resolution.to} />;
  } else {
    page = <NotFoundPage />;
  }

  return (
    <>
      <div className="sc-grain" aria-hidden="true" />
      <header className="island">
        <a className="island__brand" href="#" aria-label="Axiom, back to top">
          <span>Axiom</span>
        </a>
      </header>
      {page}
    </>
  );
}
