/*
 * Page-level behaviour for a Axiom page: the homepage loader, the down-only
 * scroll rules, the scripted glides and the "no sidecars" and tools auto-runs,
 * the paint splats, and the reference-page reveals.
 *
 * Ported from site.js. The original was an IIFE that assumed one page load per
 * document. Here it is initSite(): it runs when a route mounts and returns a
 * teardown that removes every listener, timer, animation frame, observer,
 * Lenis instance and splat it created, so navigating between routes leaves no
 * old behaviour running.
 *
 * The engine (scrollcraft.js) is still imported as-is; this module only calls
 * its mount() and destroy() API.
 */
import "../vendor/scrollcraft/scrollcraft.js";
import type { LenisInstance } from "../types/globals";
import type { IntroPlan } from "./intro";
import { mountPaint, type PaintHandle } from "./paint";
import { playSwirl } from "./swirl";

export type SiteKind = "home" | "doc";

export interface InitSiteOptions {
  /** "home" for the homepage, "doc" for every other page. */
  kind: SiteKind;
  /** The element that contains the page's <main>. Scoped queries stay inside it. */
  root: HTMLElement;
  /** The loading overlay, rendered only when the homepage intro is planned. */
  loader: HTMLElement | null;
  plan: IntroPlan;
}

interface Splat {
  act: HTMLElement;
  at: number;
  paint: PaintHandle;
  docRun: boolean;
  assisted: boolean;
  ran: boolean;
}

interface FlowBox {
  el: HTMLElement;
  done: boolean;
}

type Ease = (t: number) => number;

const clamp = (x: number, a: number, b: number): number => (x < a ? a : x > b ? b : x);
const easeSine: Ease = (t) => 0.5 - Math.cos(Math.PI * t) / 2;
const easeOutCubic: Ease = (t) => 1 - Math.pow(1 - t, 3);

export function initSite({ kind, root, loader, plan }: InitSiteOptions): () => void {
  const doc = kind === "doc";
  const home = kind === "home" || doc; // inner pages carry every home-page mechanic
  const guided = home || doc; // pages with the intro, locked pours and glides
  const reduce = window.ScrollCraft.reduce;
  const docEl = document.documentElement;

  // ---- lifecycle bookkeeping -------------------------------------------------
  let dead = false;
  const teardowns: Array<() => void> = [];
  const timers = new Set<number>();
  const frames = new Set<number>();

  const later = (fn: () => void, ms: number): void => {
    const id = window.setTimeout(() => {
      timers.delete(id);
      if (!dead) fn();
    }, ms);
    timers.add(id);
  };
  const schedule = (fn: (t: number) => void): number => {
    const id = requestAnimationFrame((t) => {
      frames.delete(id);
      if (!dead) fn(t);
    });
    frames.add(id);
    return id;
  };
  const cancelScheduled = (id: number): void => {
    cancelAnimationFrame(id);
    frames.delete(id);
  };
  const listen = (
    target: EventTarget,
    type: string,
    fn: (e: Event) => void,
    opts?: AddEventListenerOptions | boolean,
  ): void => {
    target.addEventListener(type, fn, opts);
    teardowns.push(() => target.removeEventListener(type, fn, opts));
  };
  const $ = (sel: string): HTMLElement | null => root.querySelector<HTMLElement>(sel);
  const $$ = (sel: string): HTMLElement[] => Array.from(root.querySelectorAll<HTMLElement>(sel));

  teardowns.push(() => {
    timers.forEach((id) => window.clearTimeout(id));
    timers.clear();
    frames.forEach((id) => cancelAnimationFrame(id));
    frames.clear();
  });

  // ---- shared state ----------------------------------------------------------
  // `autoOn` is the locked "no sidecars" run, `gliding` is any scripted scroll
  // (a nav click or the climb back to the top).
  let introOn = plan === "loader" && !reduce && !!loader;
  let autoOn = false;
  let gliding = false;
  let rising = false;
  let skipAuto = false;
  let navigating = false;
  let floorY = 0; // the furthest point reached; the page never goes above it
  let holdY = 0;
  let paintWasBusy = false;
  let glideRaf = 0;
  let autoDone = false;
  let toolsDone = false;
  let lastY = window.scrollY;
  let swirl: (() => void) | null = null;
  let lenis: LenisInstance | null = null;
  const splats: Splat[] = [];
  const AUTO_MS = 4500;
  const TOOLS_MS = 4200;
  const DOC_MS = 4800;

  const peak = $("#peak");
  const tools = $("#work");

  // ---- entrance (sub-pages) ---------------------------------------------------
  // The hook has already added `intro-out`, which starts the hero entrance. It
  // is released once those animations have finished, as the original did.
  if (plan === "entrance") later(() => docEl.classList.remove("intro-out"), 2800);

  // ---- homepage loader --------------------------------------------------------
  // Loose file chips spiral into a vortex, the vortex is fallen through, and the
  // hero letters spiral into place. It waits for fonts and the load event (at
  // least MIN ms), never longer than MAX. Scrolling is held until it is over.
  if (introOn && loader) {
    const el = loader;
    const t0 = performance.now();
    const MIN = 2300;
    const MAX = 4500;
    let out = false;
    const NAMES = [
      "Cargo.toml", "go.mod", "Makefile", ".gitignore", "build.rs", "manifest.json",
      "checksums.txt", "signature.sig", "package.json", "Dockerfile", "setup.py",
      "README.md", ".env", "cache/", "vendor/", "go.sum", "index.db", "lock.pid",
      "tsconfig.json", "config.cmake", "Cargo.lock", ".DS_Store",
    ];
    let html =
      '<i class="intro__disc"></i><i class="intro__disc intro__disc--b"></i><i class="intro__core"></i>';
    NAMES.forEach((name) => {
      const rn = Math.random;
      const a = rn() * 360;
      const r = 22 + rn() * 34;
      const d = rn() * 0.55;
      const z = (rn() - 0.5) * 480;
      const dir = 1;
      const du = 1.6 + rn() * 0.8;
      const sp = 520 + rn() * 380;
      html +=
        `<span class="ip" style="--a:${a.toFixed(0)}deg;--d:${d.toFixed(2)}s;--du:${du.toFixed(2)}s;` +
        `--sp:${sp.toFixed(0)};--dir:${dir}"><b style="--r:${r.toFixed(0)}vmax;--z:${z.toFixed(0)}px">` +
        `${name}</b></span>`;
    });
    el.innerHTML = html;

    const introOut = (): void => {
      if (out) return;
      out = true;
      docEl.classList.add("intro-out");
      later(() => {
        el.style.display = "none";
      }, 1100);
      later(() => {
        docEl.classList.remove("intro-on", "intro-out");
        introOn = false;
      }, 2800);
    };
    const fontsReady = Promise.race([
      document.fonts ? document.fonts.ready : Promise.resolve(),
      new Promise<void>((resolve) => later(() => resolve(), MAX)),
    ]);
    const loaded: Promise<void> =
      document.readyState === "complete"
        ? Promise.resolve()
        : new Promise<void>((resolve) => {
            window.addEventListener("load", () => resolve(), { once: true });
          });
    void Promise.all([fontsReady, loaded]).then(() => {
      if (!dead) later(introOut, Math.max(0, MIN - (performance.now() - t0)));
    });
    later(introOut, MAX + 1500);
  }

  // ---- reference pages: reveal content blocks once on entry -------------------
  if (doc) {
    $$(".sec .head, .sec .prose, .sec pre, .sec .note, .sec .rows, .sec .scroll, .sec .cta, .sec > .sc-wrap > div[style]")
      .forEach((el) => el.setAttribute("data-sc-in", ""));
    $$(".sec .list").forEach((el) => {
      el.setAttribute("data-sc-in", "");
      el.setAttribute("data-sc-stagger", "60");
    });
  }

  // The home page always opens at the top, and the browser must not restore a
  // deeper position, because the page only goes down.
  if (home) {
    try {
      history.scrollRestoration = "manual";
    } catch {
      /* not supported: nothing to restore */
    }
    if (!window.location.hash) window.scrollTo({ top: 0, behavior: "instant" });
  }

  const sc = window.ScrollCraft.mount(root);
  teardowns.push(() => sc.destroy());

  // ---- paint splats: started by position, once, and cleared only while off screen
  root.querySelectorAll<HTMLCanvasElement>("section canvas.paint").forEach((canvas) => {
    const act = canvas.closest("section") as HTMLElement;
    splats.push({
      act,
      at: 0.02,
      paint: mountPaint(canvas),
      docRun: guided && (act.classList.contains("approach--doc") || act.hasAttribute("data-autorun")),
      assisted: false,
      ran: false,
    });
  });
  teardowns.push(() => splats.forEach((s) => s.paint.destroy()));

  // Reference pages: every flow section and the closing block get the same quick
  // nudge the painted acts get.
  const flows: FlowBox[] = doc
    ? $$(".sec, .close").map((el) => ({ el, done: false }))
    : [];

  function paintBusy(): boolean {
    for (const s of splats) if (s.paint.state() === "running") return true;
    return false;
  }

  // ---- inertia scrolling (Lenis, from the CDN) ---------------------------------
  // It smooths the native scroll the engine already reads; the page works the
  // same without it.
  if (window.Lenis && !reduce) {
    const lz = new window.Lenis({ lerp: 0.075, wheelMultiplier: 0.9, touchMultiplier: 1.1, smoothWheel: true });
    lenis = lz;
    // Each section has its own feel. The values ease between sections so
    // nothing lurches at a boundary.
    const FEEL = [
      { sel: ".hero", lerp: 0.065, wheel: 0.7 },
      { sel: "#peak", lerp: 0.045, wheel: 0.55 },
      { sel: "#approach", lerp: 0.07, wheel: 0.85 },
      { sel: "#work", lerp: 0.12, wheel: 1.15 },
      { sel: ".approach ~ .sec", lerp: 0.12, wheel: 1.15 },
      { sel: "#contact", lerp: 0.1, wheel: 1.0 },
    ].map((f) => ({ ...f, el: $(f.sel) }));
    const feel = { lerp: 0.1, wheel: 1.0 };
    lz.options.prevent = () => introOn || autoOn || gliding || paintBusy();
    const tick = (t: number): void => {
      const mid = window.scrollY + window.innerHeight * 0.5;
      let tgt = FEEL[0];
      for (const f of FEEL) {
        if (!f.el) continue;
        const top = f.el.getBoundingClientRect().top + window.scrollY;
        if (mid >= top) tgt = f;
      }
      feel.lerp += (tgt.lerp - feel.lerp) * 0.06;
      feel.wheel += (tgt.wheel - feel.wheel) * 0.06;
      try {
        lz.options.lerp = feel.lerp;
        lz.options.wheelMultiplier = feel.wheel;
      } catch {
        /* options not writable in this Lenis build */
      }
      lz.raf(t);
      schedule(tick);
    };
    tick(performance.now());
    teardowns.push(() => {
      lz.destroy();
      lenis = null;
    });
  }

  // Jump to a position with no easing and no CSS smooth-scroll in the way.
  function setY(y: number): void {
    if (lenis) lenis.scrollTo(y, { immediate: true, force: true });
    else window.scrollTo({ top: y, behavior: "instant" });
  }

  // One scripted glide at a time. Input is ignored while it runs. Reduced motion jumps.
  function glide(toY: number, seconds: number, done: (() => void) | null, ease: Ease = easeSine): void {
    cancelScheduled(glideRaf);
    const fromY = window.scrollY;
    if (reduce || Math.abs(toY - fromY) < 2) {
      setY(toY);
      gliding = false;
      if (done) done();
      return;
    }
    gliding = true;
    const t0 = performance.now();
    const ms = seconds * 1000;
    const step = (now: number): void => {
      const u = clamp((now - t0) / ms, 0, 1);
      setY(fromY + (toY - fromY) * ease(u));
      if (u < 1) glideRaf = schedule(step);
      else {
        gliding = false;
        if (done) done();
      }
    };
    step(t0);
  }

  // Landing positions for pinned acts. A pinned act's anchor sits at p = 0, which
  // is its emptiest frame, so in-page links land part-way in, where it reads.
  const LAND: Record<string, number> = { approach: 0.04, work: 0.58 };
  function targetY(id: string): number | null {
    const el = $("#" + id);
    if (!el) return null;
    const top = el.getBoundingClientRect().top + window.scrollY;
    const f: number | undefined = LAND[id];
    return f == null ? top : top + Math.max(el.offsetHeight - window.innerHeight, 0) * f;
  }

  // The way up is a fake: the portal covers the screen, the page is teleported to
  // the top while it is fully covered, and the cover clears.
  function swirlUp(): void {
    const arrive = (): void => {
      setY(0);
      floorY = 0;
      resetAll();
    };
    rising = true;
    if (reduce || !document.body.animate) {
      arrive();
      rising = false;
      return;
    }
    gliding = true;
    swirl = playSwirl({
      onCovered: arrive,
      onClearing: () => {
        rising = false;
      },
      onDone: () => {
        swirl = null;
        gliding = false;
      },
    });
  }
  teardowns.push(() => {
    if (swirl) swirl();
    swirl = null;
  });

  // ---- down-only scroll -----------------------------------------------------------
  // Every way of going up is refused at the source: wheel, touch, keys. The
  // per-frame clamp further down catches anything that still leaks through.
  if (guided) {
    const UPKEYS: Record<number, true> = { 33: true, 36: true, 38: true }; // PageUp, Home, ArrowUp
    const NAVKEYS: Record<number, true> = { 32: true, 33: true, 34: true, 35: true, 36: true, 37: true, 38: true, 39: true, 40: true };
    const busy = (): boolean => introOn || autoOn || gliding || paintBusy();

    listen(
      window,
      "wheel",
      (e) => {
        const w = e as WheelEvent;
        if (w.ctrlKey) return; // pinch-zoom
        if (busy() || (home && w.deltaY < 0)) {
          w.preventDefault();
          w.stopPropagation();
        }
      },
      { passive: false, capture: true },
    );

    let touchY = 0;
    listen(
      window,
      "touchstart",
      (e) => {
        const t = e as TouchEvent;
        if (t.touches.length === 1) touchY = t.touches[0].clientY;
      },
      { passive: true, capture: true },
    );
    listen(
      window,
      "touchmove",
      (e) => {
        const t = e as TouchEvent;
        if (t.touches.length !== 1) {
          if (busy() && t.cancelable) t.preventDefault();
          return;
        }
        const y = t.touches[0].clientY;
        const dy = y - touchY;
        touchY = y;
        // finger moving down = page moving up
        if ((busy() || (home && dy > 0)) && t.cancelable) t.preventDefault();
      },
      { passive: false, capture: true },
    );

    listen(
      window,
      "keydown",
      (e) => {
        const k = e as KeyboardEvent;
        if (k.key === "Escape" && autoOn) {
          skipAuto = true;
          return;
        }
        if (k.altKey || k.ctrlKey || k.metaKey) return;
        const up = home && (UPKEYS[k.keyCode] || (k.keyCode === 32 && k.shiftKey));
        if ((busy() && NAVKEYS[k.keyCode]) || up) k.preventDefault();
      },
      true,
    );

    // A resized window re-lays the page out, so the old pixel floor means
    // nothing. Restart it from wherever the reader now is.
    listen(
      window,
      "resize",
      () => {
        if (!rising) floorY = window.scrollY;
      },
      { passive: true },
    );
  }

  // ---- links ------------------------------------------------------------------------
  // The Axiom pill only ever takes you to the top of the page you are on (the
  // Home button is the way to /). Links to sections below glide down. Links to
  // sections already behind are inert.
  if (guided) {
    listen(document, "click", (e) => {
      const target = e.target as Element | null;
      const a = target && typeof target.closest === "function" ? target.closest("a[href^='#']") : null;
      if (!a) return;
      e.preventDefault();
      if (gliding || autoOn || introOn) return;
      const id = (a.getAttribute("href") ?? "").slice(1);
      const vh = window.innerHeight;

      if (id === "") {
        // Axiom: back to the top
        if (window.scrollY < 2) return;
        swirlUp();
        return;
      }
      if (paintBusy()) return;
      const y = targetY(id);
      if (y == null || y <= floorY - 2) return; // behind: the page only goes down
      navigating = true;
      glide(y, clamp(1.4 + ((y - window.scrollY) / vh) * 0.2, 1.6, 3.2), () => {
        navigating = false;
      });
    });

    if (home && window.location.hash) {
      const hid = window.location.hash.slice(1);
      schedule(() => {
        later(() => {
          const y = targetY(hid);
          if (y != null) setY(y);
        }, 0);
      });
    }
  }

  // Keyboard focus on a bar that has not wiped open yet: bring the act to its
  // settled middle, the same way the engine does for cues.
  listen(document, "focusin", (e) => {
    const t = e.target as Element | null;
    const tool = t && typeof t.closest === "function" ? t.closest(".tool") : null;
    if (!tool) return;
    const p = parseFloat(tools ? tools.style.getPropertyValue("--sc-p") : "");
    if (!isNaN(p) && p < 0.5) {
      const y = targetY("work");
      if (y != null && y >= floorY - 2) setY(y);
    }
  });

  // ---- scripted runs ---------------------------------------------------------------
  // Back at the top every painted act is off screen below, so wiping them now is
  // invisible. During the climb nothing is touched.
  function resetAll(): void {
    splats.forEach((sp) => {
      sp.paint.reset();
      sp.assisted = false;
      sp.ran = false;
    });
    autoDone = false;
    toolsDone = false;
    flows.forEach((f) => {
      f.done = false;
    });
  }

  function assist(sp: Splat, topY: number): void {
    const d = topY - window.scrollY;
    // A quick nudge: short, and fastest at the start so it settles into place.
    glide(
      topY,
      clamp(0.2 + (d / window.innerHeight) * 0.25, 0.22, 0.42),
      () => {
        if (sp.act === peak && !autoDone) runPeak();
      },
      easeOutCubic,
    );
  }

  // The "no sidecars" auto-run. The act plays by itself. When it is entered from
  // above, scrolling is locked and the page glides through it on a fixed
  // timeline, then hands control back. Esc skips it.
  function peakTop(): number {
    return peak ? peak.getBoundingClientRect().top + window.scrollY : 0;
  }
  function runPeak(): void {
    if (!peak) return;
    autoOn = true;
    autoDone = true;
    skipAuto = false;
    const startY = window.scrollY;
    const endY = peakTop() + Math.max(peak.offsetHeight - window.innerHeight, 0);
    const t0 = performance.now();
    const step = (now: number): void => {
      let t = clamp((now - t0) / AUTO_MS, 0, 1);
      if (skipAuto) t = 1;
      setY(startY + (endY - startY) * easeSine(t));
      if (t < 1) schedule(step);
      else autoOn = false;
    };
    step(t0);
  }

  // The tools act plays by itself too: a slow, locked glide through the three bars.
  function toolsTop(): number {
    return tools ? tools.getBoundingClientRect().top + window.scrollY : 0;
  }
  function runToolsAuto(): void {
    if (!tools) return;
    autoOn = true;
    skipAuto = false;
    const startY = window.scrollY;
    const endY = toolsTop() + Math.max(tools.offsetHeight - window.innerHeight, 0);
    const t0 = performance.now();
    const step = (now: number): void => {
      let t = clamp((now - t0) / TOOLS_MS, 0, 1);
      if (skipAuto) t = 1;
      setY(startY + (endY - startY) * easeSine(t));
      if (t < 1) schedule(step);
      else autoOn = false;
    };
    step(t0);
  }
  function runTools(): void {
    if (!tools) return;
    toolsDone = true;
    const topY = toolsTop();
    const d = topY - window.scrollY;
    if (d <= 2) {
      runToolsAuto();
      return;
    }
    // The same quick nudge the painted acts use, then the act plays by itself.
    glide(topY, clamp(0.2 + (d / window.innerHeight) * 0.25, 0.22, 0.42), runToolsAuto, easeOutCubic);
  }

  function runDocAuto(act: HTMLElement): void {
    autoOn = true;
    skipAuto = false;
    const startY = window.scrollY;
    const endY = act.getBoundingClientRect().top + window.scrollY + Math.max(act.offsetHeight - window.innerHeight, 0);
    // Same pace everywhere: a longer act takes proportionally longer.
    const ms = DOC_MS * clamp((endY - startY) / (window.innerHeight * 1.2), 1, 1.6);
    const t0 = performance.now();
    const step = (now: number): void => {
      let t = clamp((now - t0) / ms, 0, 1);
      if (skipAuto) t = 1;
      setY(startY + (endY - startY) * easeSine(t));
      if (t < 1) schedule(step);
      else autoOn = false;
    };
    step(t0);
  }

  // ---- per frame ----------------------------------------------------------------------
  function watchPage(): void {
    let y = window.scrollY;
    const vh = window.innerHeight;

    if (introOn && y > 0) {
      setY(0);
      y = 0;
    }
    // Locked pour: freeze the page where it is, momentum included.
    const pb = paintBusy();
    if (pb && !paintWasBusy) {
      holdY = y;
      if (lenis) lenis.scrollTo(holdY, { immediate: true, force: true });
    }
    paintWasBusy = pb;
    if (pb && !autoOn && !gliding && !rising && Math.abs(y - holdY) > 0.5) {
      setY(holdY);
      y = holdY;
    }

    // Down-only: remember the furthest point, and put the page back if anything
    // pushed it above that.
    if (home && !rising) {
      const maxY = Math.max(document.documentElement.scrollHeight - vh, 0);
      if (floorY > maxY) floorY = maxY;
      if (y < floorY - 1 && !gliding) {
        setY(floorY);
        y = floorY;
      } else if (y > floorY) floorY = y;
    }

    if (peak && !autoOn && !gliding && !navigating && !reduce) {
      const top = peakTop();
      if (!rising && y < top - vh * 1.2) autoDone = false;
      if (!autoDone && y >= top - 2 && y < top + vh * 0.6 && y > lastY) runPeak();
    }
    if (tools && !autoOn && !gliding && !navigating && !reduce) {
      const tt = toolsTop();
      if (!rising && y < tt - vh * 1.2) toolsDone = false;
      if (!toolsDone && !rising && y >= tt - vh * 0.35 && y < tt + vh * 0.6) runTools();
    }
    const movingDown = y > lastY;
    lastY = y;

    for (const fl of flows) {
      const fr = fl.el.getBoundingClientRect();
      if (!fl.done && !reduce && movingDown && !gliding && !autoOn && !navigating && !rising && !paintBusy() && fr.top > 2 && fr.top < vh * 0.75) {
        fl.done = true;
        glide(y + fr.top, clamp(0.2 + (fr.top / vh) * 0.25, 0.22, 0.42), null, easeOutCubic);
      } else if (fr.top >= vh) {
        fl.done = false;
      }
    }

    for (const sp of splats) {
      const r = sp.act.getBoundingClientRect();
      if (guided && !reduce && !sp.assisted && movingDown && !gliding && !autoOn && !navigating && !paintBusy() && r.top > 2 && r.top < vh * 0.75) {
        sp.assisted = true;
        assist(sp, y + r.top);
      }
      if (sp.docRun && sp.assisted && !sp.ran && !reduce && !autoOn && !gliding && !navigating && sp.paint.state() === "done" && r.top <= 4 && r.top > -vh * 0.5) {
        sp.ran = true;
        runDocAuto(sp.act);
      }
      if (rising) continue;
      if (r.top <= vh * sp.at && r.bottom > 0) sp.paint.play();
      else if (r.top >= vh) {
        sp.paint.reset();
        sp.assisted = false;
        sp.ran = false;
      }
    }

    schedule(watchPage);
  }
  watchPage();

  // Test hook: the verification harness reads the live engine instance through it.
  window.__sc = sc;
  teardowns.push(() => {
    delete window.__sc;
  });

  return () => {
    if (dead) return;
    dead = true;
    for (const fn of teardowns) fn();
    teardowns.length = 0;
  };
}
