import { createRoot } from "react-dom/client";
import "./vendor/scrollcraft/scrollcraft.css";
import "./styles/site.css";
import { App } from "./app/App";
import { installRouter, normalizeInitialUrl } from "./router/router";

// The app decides where the page starts. The browser must not restore a scroll
// position on its own, because the pages are scroll-driven.
try {
  history.scrollRestoration = "manual";
} catch {
  /* not supported: nothing to restore */
}

// Clean the address bar first (/index.html, /poly.html, trailing slashes, /jiggle),
// then start listening for navigation, then render.
normalizeInitialUrl();
installRouter();

const container = document.getElementById("root");
if (!container) throw new Error("index.html has no #root element");
createRoot(container).render(<App />);
